msg.payload = {
    sensor_id: "sensor_001",
    tipo: "ambiental",
    temperatura: Math.floor(Math.random() * 15) + 20,
    humidade: Math.floor(Math.random() * 40) + 40,
    timestamp: new Date().toISOString()
};

return msg;

let data = msg.payload;

// Converter valores para número
const temperatura = Number(data.temperatura);
const humidade = Number(data.humidade);

// -------------------------------------------------
// CONFIGURAÇÃO ATIVA
// -------------------------------------------------

const config = global.get("dashboardConfig");

if (!config) {
    node.error("Configuração ativa não encontrada", msg);
    return null;
}

// Procurar o sensor_001 em todas as zonas
let sensorConfig = null;

for (const zone of config.zones) {
    const sensor = zone.sensors.find(
        s => s.id === "sensor_001"
    );

    if (sensor) {
        sensorConfig = sensor;
        break;
    }
}

if (!sensorConfig) {
    node.error(
        "sensor_001 não encontrado na configuração ativa",
        msg
    );
    return null;
}

// Procurar configuração das métricas
const tempConfig = sensorConfig.metrics.find(
    metric => metric.field === "temperatura"
);

const humConfig = sensorConfig.metrics.find(
    metric => metric.field === "humidade"
);

if (!tempConfig || !humConfig) {
    node.error(
        "Configuração de temperatura ou humidade não encontrada",
        msg
    );
    return null;
}

// Limites provenientes do cenário ativo
const tempMin = Number(tempConfig.alerts.min);
const tempMax = Number(tempConfig.alerts.max);

const humMin = Number(humConfig.alerts.min);
const humMax = Number(humConfig.alerts.max);

// -------------------------------------------------
// HISTÓRICO
// -------------------------------------------------

let history = context.get("history") || [];

history.push({
    temperatura: temperatura,
    humidade: humidade,
    timestamp: data.timestamp
});

if (history.length > 5) {
    history = history.slice(-5);
}

context.set("history", history);

// Função para calcular média
function average(values) {
    if (values.length === 0) {
        return 0;
    }

    const total = values.reduce(
        (sum, value) => sum + Number(value),
        0
    );

    return total / values.length;
}

// Médias móveis
const tempAvg = average(
    history.map(item => item.temperatura)
);

const humAvg = average(
    history.map(item => item.humidade)
);

// -------------------------------------------------
// THRESHOLDS DINÂMICOS
// -------------------------------------------------

let alerts = [];

if (temperatura < tempMin) {
    alerts.push("Temperatura abaixo do limite");
}

if (temperatura > tempMax) {
    alerts.push("Temperatura acima do limite");
}

if (humidade < humMin) {
    alerts.push("Humidade abaixo do limite");
}

if (humidade > humMax) {
    alerts.push("Humidade acima do limite");
}

// -------------------------------------------------
// DETEÇÃO DE TENDÊNCIA
// -------------------------------------------------

let tempTrend = "estável";
let humTrend = "estável";

if (history.length >= 3) {

    const firstReading = history[0];
    const lastReading = history[history.length - 1];

    const tempDifference =
        lastReading.temperatura - firstReading.temperatura;

    const humDifference =
        lastReading.humidade - firstReading.humidade;

    // Tendência da temperatura
    if (tempDifference >= 5) {
        tempTrend = "subida rápida";
    } else if (tempDifference >= 2) {
        tempTrend = "subida gradual";
    } else if (tempDifference <= -5) {
        tempTrend = "descida rápida";
    } else if (tempDifference <= -2) {
        tempTrend = "descida gradual";
    } else {
        tempTrend = "estável";
    }

    // Tendência da humidade
    if (humDifference >= 10) {
        humTrend = "subida rápida";
    } else if (humDifference >= 4) {
        humTrend = "subida gradual";
    } else if (humDifference <= -10) {
        humTrend = "descida rápida";
    } else if (humDifference <= -4) {
        humTrend = "descida gradual";
    } else {
        humTrend = "estável";
    }
}

// -------------------------------------------------
// DETEÇÃO DE ANOMALIAS
// -------------------------------------------------

let anomaly = false;

if (Math.abs(temperatura - tempAvg) > 6) {
    anomaly = true;

    alerts.push(
        "Anomalia: variação brusca de temperatura"
    );
}

if (Math.abs(humidade - humAvg) > 15) {
    anomaly = true;

    alerts.push(
        "Anomalia: variação brusca de humidade"
    );
}

// -------------------------------------------------
// ESTADO GERAL
// -------------------------------------------------

let estado = "normal";

if (alerts.length > 0) {
    estado = "aviso";
}

if (anomaly) {
    estado = "alerta";
}

// -------------------------------------------------
// RESULTADO DA ANÁLISE
// -------------------------------------------------

msg.payload = {
    ...data,

    temperatura: temperatura,
    humidade: humidade,

    analytics: {
        temperatura_media_movel:
            Number(tempAvg.toFixed(2)),

        humidade_media_movel:
            Number(humAvg.toFixed(2)),

        tendencia_temperatura:
            tempTrend,

        tendencia_humidade:
            humTrend,

        estado:
            estado,

        anomalia:
            anomaly,

        alertas:
            alerts,

        limites: {
            temperatura: {
                min: tempMin,
                max: tempMax
            },

            humidade: {
                min: humMin,
                max: humMax
            }
        },

        scenario:
            config.scenario.id
    }
};

return msg;

msg.payload = {
    sensor_id: "sensor_002",
    tipo: "luminosidade",
    luminosidade: Math.floor(Math.random() * 1000),
    timestamp: new Date().toISOString()
};

return msg;

let data = msg.payload;

// Converter luminosidade para número
const luminosidade = Number(data.luminosidade);

// -------------------------------------------------
// CONFIGURAÇÃO ATIVA
// -------------------------------------------------

const config = global.get("dashboardConfig");

if (!config) {
    node.error("Configuração ativa não encontrada", msg);
    return null;
}

// Procurar o sensor_002 em todas as zonas
let sensorConfig = null;

for (const zone of config.zones) {
    const sensor = zone.sensors.find(
        s => s.id === "sensor_002"
    );

    if (sensor) {
        sensorConfig = sensor;
        break;
    }
}

if (!sensorConfig) {
    node.error(
        "sensor_002 não encontrado na configuração ativa",
        msg
    );
    return null;
}

// Procurar configuração da luminosidade
const luminosityConfig = sensorConfig.metrics.find(
    metric => metric.field === "luminosidade"
);

if (!luminosityConfig) {
    node.error(
        "Configuração de luminosidade não encontrada",
        msg
    );
    return null;
}

// Limites provenientes do cenário ativo
const luminosityMin =
    Number(luminosityConfig.alerts.min);

const luminosityMax =
    Number(luminosityConfig.alerts.max);

// -------------------------------------------------
// HISTÓRICO
// -------------------------------------------------

let history =
    context.get("history_luminosidade") || [];

history.push({
    luminosidade: luminosidade,
    timestamp: data.timestamp
});

if (history.length > 5) {
    history = history.slice(-5);
}

context.set("history_luminosidade", history);

// Função para calcular média
function average(values) {
    if (values.length === 0) {
        return 0;
    }

    const total = values.reduce(
        (sum, value) => sum + Number(value),
        0
    );

    return total / values.length;
}

// Média móvel
const luminosityAvg = average(
    history.map(item => item.luminosidade)
);

// -------------------------------------------------
// THRESHOLDS DINÂMICOS
// -------------------------------------------------

let alerts = [];

if (luminosidade < luminosityMin) {
    alerts.push("Luminosidade abaixo do limite");
}

if (luminosidade > luminosityMax) {
    alerts.push("Luminosidade acima do limite");
}

// -------------------------------------------------
// TENDÊNCIA
// -------------------------------------------------

let trend = "estável";

if (history.length >= 3) {

    const firstValue =
        history[0].luminosidade;

    const lastValue =
        history[history.length - 1].luminosidade;

    const difference =
        lastValue - firstValue;

    if (difference >= 200) {
        trend = "subida rápida";
    } else if (difference >= 80) {
        trend = "subida gradual";
    } else if (difference <= -200) {
        trend = "descida rápida";
    } else if (difference <= -80) {
        trend = "descida gradual";
    }
}

// -------------------------------------------------
// ANOMALIA
// -------------------------------------------------

let anomaly = false;

if (
    Math.abs(
        luminosidade - luminosityAvg
    ) > 300
) {
    anomaly = true;

    alerts.push(
        "Anomalia: variação brusca de luminosidade"
    );
}

// -------------------------------------------------
// ESTADO GERAL
// -------------------------------------------------

let estado = "normal";

if (alerts.length > 0) {
    estado = "aviso";
}

if (anomaly) {
    estado = "alerta";
}

// -------------------------------------------------
// RESULTADO
// -------------------------------------------------

msg.payload = {
    ...data,

    luminosidade: luminosidade,

    analytics: {
        luminosidade_media_movel:
            Number(luminosityAvg.toFixed(2)),

        tendencia_luminosidade:
            trend,

        estado:
            estado,

        anomalia:
            anomaly,

        alertas:
            alerts,

        limites: {
            luminosidade: {
                min: luminosityMin,
                max: luminosityMax
            }
        },

        scenario:
            config.scenario.id
    }
};

return msg;

msg.payload = {
    sensor_id: "sensor_003",
    tipo: "movimento",
    movimento: Math.random() > 0.7,
    timestamp: new Date().toISOString()
};

return msg;

let data = msg.payload;

// Converter movimento para booleano
const movimento =
    data.movimento === true ||
    data.movimento === "true" ||
    data.movimento === 1;

// Histórico específico do sensor de movimento
let history = context.get("history_movimento") || [];

// Adicionar nova leitura
history.push({
    movimento: movimento,
    timestamp: data.timestamp
});

// Manter apenas as últimas 10 leituras
if (history.length > 10) {
    history = history.slice(-10);
}

context.set("history_movimento", history);

// -------------------------------------------------
// CONTAGEM DE MOVIMENTO
// -------------------------------------------------

const motionCount = history.filter(
    item => item.movimento === true
).length;

// -------------------------------------------------
// ESTADO DE ATIVIDADE
// -------------------------------------------------

let atividade = "sem movimento";

if (movimento) {
    atividade = "movimento detetado";
}

if (motionCount >= 7) {
    atividade = "atividade elevada";
}

// -------------------------------------------------
// ALERTAS
// -------------------------------------------------

let alerts = [];

if (motionCount >= 7) {
    alerts.push(
        "Atividade elevada: movimento detetado frequentemente"
    );
}

// -------------------------------------------------
// ANOMALIA
// -------------------------------------------------

let anomaly = false;

// Considerar anómala uma atividade muito frequente
// nas últimas 10 leituras
if (motionCount >= 9) {
    anomaly = true;

    alerts.push(
        "Anomalia: movimento persistente"
    );
}

// -------------------------------------------------
// ESTADO GERAL
// -------------------------------------------------

let estado = "normal";

if (alerts.length > 0) {
    estado = "aviso";
}

if (anomaly) {
    estado = "alerta";
}

// -------------------------------------------------
// RESULTADO
// -------------------------------------------------

msg.payload = {
    ...data,

    movimento: movimento,

    analytics: {
        atividade_movimento:
            atividade,

        movimentos_recentes:
            motionCount,

        estado:
            estado,

        anomalia:
            anomaly,

        alertas:
            alerts
    }
};

return msg;

msg.method = "PATCH";
msg.url = "http://orion:1026/v2/entities/Sensor001/attrs";

msg.headers = {
    "Content-Type": "application/json"
};

msg.payload = {
    temperature: {
        value: msg.payload.temperatura,
        type: "Number"
    },
    humidity: {
        value: msg.payload.humidade,
        type: "Number"
    },
    anomaly: {
        value: msg.payload.analytics?.anomalia || false,
        type: "Boolean"
    },
    trend: {
        value: msg.payload.analytics?.tendencia || "estável",
        type: "Text"
    }
};

return msg;

const data = msg.payload;

let entityId = null;
let payload = {};

if (data.sensor_id === "sensor_001") {
    entityId = "Sensor001";

    payload = {
        temperature: {
            value: data.temperatura,
            type: "Number"
        },
        humidity: {
            value: data.humidade,
            type: "Number"
        },
        anomaly: {
            value: data.analytics?.anomalia || false,
            type: "Boolean"
        },
        trend: {
            value: data.analytics?.tendencia || "estável",
            type: "Text"
        }
    };
}

if (data.sensor_id === "sensor_002") {
    entityId = "Sensor002";

    payload = {
        luminosity: {
            value: data.luminosidade,
            type: "Number"
        }
    };
}

if (data.sensor_id === "sensor_003") {
    entityId = "Sensor003";

    payload = {
        motion: {
            value: data.movimento,
            type: "Boolean"
        }
    };
}

if (!entityId) {
    node.warn("Sensor desconhecido: " + data.sensor_id);
    return null;
}

msg.method = "PATCH";
msg.url = `http://orion:1026/v2/entities/${entityId}/attrs`;
msg.headers = {
    "Content-Type": "application/json"
};
msg.payload = payload;

return msg;

const config = msg.payload;

// Guardar a configuração ativa completa
// no contexto global do Node-RED
global.set("dashboardConfig", config);

// Manter a informação no payload para conseguirmos
// confirmar no Debug que foi guardada
msg.payload = {
    status: "Configuração guardada",
    scenario: config.scenario.id,
    name: config.scenario.name
};

return msg;

const config = global.get("dashboardConfig");

if (!config) {
    node.error("Configuração global não encontrada");
    return null;
}

msg.payload = {
    scenario: config.scenario.id,
    temperaturaMin:
        config.zones[0].sensors[0].metrics
            .find(m => m.field === "temperatura")
            .alerts.min,

    temperaturaMax:
        config.zones[0].sensors[0].metrics
            .find(m => m.field === "temperatura")
            .alerts.max
};

return msg;

msg.payload = {
    sensor_id: "sensor_004",
    tipo: "agricultura",
    humidade_solo: Math.floor(Math.random() * 61) + 20,
    timestamp: new Date().toISOString()
};
return msg;

let total = context.get("total") ?? 125;
total += Math.round((Math.random() * 2 + 0.2) * 100) / 100;
context.set("total", total);
msg.payload = {
    sensor_id: "sensor_005",
    tipo: "domotica",
    consumo_agua: Math.round(total * 100) / 100,
    timestamp: new Date().toISOString()
};
return msg;

let total = context.get("total") ?? 250;
total += Math.round((Math.random() * 0.3 + 0.02) * 1000) / 1000;
context.set("total", total);
msg.payload = {
    sensor_id: "sensor_006",
    tipo: "industrial",
    consumo_energetico: Math.round(total * 1000) / 1000,
    timestamp: new Date().toISOString()
};
return msg;
